        ? action === 'settle'
          ? 'Whoever opened this claim cannot also settle it: another user must settle it.'
          : action === 'resettle'
          ? 'Only a steward can re-settle a claim.'
          : action === 'void'
          ? claim.status === 'SETTLED'
